css:
.sticksim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1f2a36;
    background: linear-gradient(180deg, #eef4fb 0%, #f6f9fc 40%, #ffffff 100%);
    border-radius: 18px;
}

.sticksim-container * {
    box-sizing: border-box;
}

.sticksim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #005eb5 0%, #0b7ec4 55%, #109b8e 100%);
    color: #ffffff;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 12px 30px rgba(0, 94, 181, 0.28);
}

.sticksim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.sticksim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.1px;
    font-weight: 700;
    color: #eafaf6;
    background: rgba(255, 255, 255, 0.16);
    border: 1px solid rgba(255, 255, 255, 0.40);
    padding: 5px 14px;
    border-radius: 999px;
}

.sticksim-subtitle {
    margin: 0 auto;
    max-width: 820px;
    font-size: 1rem;
    line-height: 1.55;
    color: #e8f3fb;
}

.sticksim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #44586c;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.sticksim-period-counter #currentDay,
.sticksim-period-counter #maxPeriods {
    font-weight: 800;
    color: #005eb5;
}

.sticksim-round-name {
    background: rgba(0, 94, 181, 0.10);
    color: #005eb5;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.sticksim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #b06a00;
    background: rgba(243, 156, 18, 0.14);
    border: 1px solid rgba(243, 156, 18, 0.38);
    padding: 4px 12px;
    border-radius: 999px;
}

.sticksim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.sticksim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #dde7f1;
    box-shadow: 0 6px 16px rgba(31, 42, 54, 0.07);
    border-top: 4px solid #005eb5;
}

.sticksim-card-adopt { border-top-color: #109b8e; }
.sticksim-card-sustain { border-top-color: #005eb5; }
.sticksim-card-engage { border-top-color: #7b61ff; }
.sticksim-card-case { border-top-color: #1f9d55; }

.sticksim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6b7c8e;
}

.sticksim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #1f2a36;
    font-variant-numeric: tabular-nums;
}

.sticksim-card-adopt .sticksim-value { color: #0e8a7e; }
.sticksim-card-sustain .sticksim-value { color: #005eb5; }
.sticksim-card-engage .sticksim-value { color: #6a4dff; }
.sticksim-card-case .sticksim-value { color: #1f9d55; }

.sticksim-sublabel {
    font-size: 0.76rem;
    color: #7e8ea0;
    line-height: 1.35;
}

.sticksim-adopt-low .sticksim-value { color: #d64545; }
.sticksim-adopt-low { border-top-color: #d64545; }
.sticksim-adopt-target .sticksim-value { color: #0e8a7e; }
.sticksim-adopt-target { border-top-color: #109b8e; }

.sticksim-sustain-high { border-top-color: #1f9d55; }
.sticksim-sustain-high .sticksim-value { color: #1f9d55; }
.sticksim-sustain-low { border-top-color: #d64545; }
.sticksim-sustain-low .sticksim-value { color: #d64545; }

.sticksim-case-negative .sticksim-value { color: #d64545; }
.sticksim-case-positive .sticksim-value { color: #1f9d55; }

.sticksim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #ffffff;
    border: 1px solid #dde7f1;
    color: #1f2a36;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
    box-shadow: 0 4px 12px rgba(31, 42, 54, 0.05);
}

.sticksim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #005eb5;
}

.sticksim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #109b8e;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(31, 42, 54, 0.07);
}

.sticksim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.sticksim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #00456b;
    margin-bottom: 6px;
}

.sticksim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #3a4a5b;
}

.sticksim-briefing-text strong { color: #005eb5; }
.sticksim-briefing-text em { color: #b06a00; font-style: italic; }

.sticksim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #dde7f1;
    box-shadow: 0 6px 16px rgba(31, 42, 54, 0.07);
}

.sticksim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #00456b;
    border-bottom: 2px solid #e4ecf4;
    padding-bottom: 8px;
}

.sticksim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2b3a49;
    margin: 14px 0 6px;
}

.sticksim-container select,
.sticksim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c6d4e2;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #ffffff;
    color: #1f2a36;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.sticksim-container select:focus,
.sticksim-container input[type="number"]:focus {
    outline: none;
    border-color: #109b8e;
    box-shadow: 0 0 0 3px rgba(16, 155, 142, 0.18);
}

.sticksim-container select option {
    background-color: #ffffff;
    color: #1f2a36;
}

.sticksim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #109b8e;
}

.sticksim-range-readout,
.sticksim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #44586c;
    margin-top: 4px;
}

.sticksim-range-readout span:last-child,
.sticksim-alloc-readout span:nth-child(2) {
    color: #0e8a7e;
    font-weight: 800;
}

.sticksim-hint {
    font-size: 0.8rem;
    color: #7e8ea0;
    margin-top: 4px;
    line-height: 1.4;
}

.sticksim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.sticksim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f4f8fc;
    border: 1px solid #dbe6f1;
    border-radius: 9px;
    padding: 8px 12px;
}

.sticksim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #2b3a49;
}

.sticksim-alloc-row input[type="number"] {
    width: 90px;
    flex: 0 0 90px;
}

.sticksim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.sticksim-container .btn-primary {
    background: linear-gradient(135deg, #005eb5 0%, #109b8e 100%);
    border: none;
    color: #ffffff;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(0, 94, 181, 0.30);
}

.sticksim-container .btn-primary:hover {
    filter: brightness(1.05);
}

.sticksim-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #c6d4e2;
    color: #44586c;
    background: transparent;
}

.sticksim-coach {
    background: linear-gradient(160deg, #00456b 0%, #086b66 100%);
    color: #eaf6f4;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 20px rgba(0, 69, 107, 0.25);
}

.sticksim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #7ee5d6;
    margin-bottom: 8px;
}

.sticksim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #eaf6f4;
}

.sticksim-coach-body strong { color: #9bf0e2; }
.sticksim-coach-body em { color: #ffd27a; font-style: italic; }

.sticksim-history,
.sticksim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #dde7f1;
    box-shadow: 0 6px 16px rgba(31, 42, 54, 0.07);
}

.sticksim-history h3,
.sticksim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #00456b;
}

.sticksim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #2b3a49;
}

.sticksim-container table#usfHistoryTable th {
    background: #eef4fb;
    color: #005eb5;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d3e0ee;
}

.sticksim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #e7eef6;
    color: #3a4a5b;
}

.sticksim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f7fafd;
}

.sticksim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .sticksim-container {
        padding: 14px;
    }
    .sticksim-header h1 {
        font-size: 1.7rem;
    }
    .sticksim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .sticksim-value {
        font-size: 2rem;
    }
    .sticksim-clock {
        margin-left: 0;
    }
    .sticksim-period-counter {
        font-size: 0.88rem;
    }
    .sticksim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .sticksim-alloc-row {
        flex-wrap: wrap;
    }
    .sticksim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .sticksim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ── v1.1.0 completion scorecard (append-only, namespaced .mis-cm-*, NHS blue/teal) ── */
.mis-cm { margin-top: 8px; }
.mis-cm-incomplete { text-align: center; color: #4a5b6b; font-size: 1rem; padding: 18px; }
.mis-cm-head { display: flex; flex-wrap: wrap; gap: 16px; align-items: stretch; margin-bottom: 18px; }
.mis-cm-score { flex: 0 0 auto; min-width: 150px; background: linear-gradient(135deg, #00456b 0%, #005eb5 55%, #109b8e 130%); color: #ffffff; border-radius: 14px; padding: 16px 22px; text-align: center; box-shadow: 0 8px 22px rgba(0, 69, 107, 0.28); }
.mis-cm-score-num { font-size: 2.9rem; font-weight: 800; line-height: 1; }
.mis-cm-score-den { font-size: 1.1rem; font-weight: 600; opacity: 0.85; }
.mis-cm-score-lbl { margin-top: 6px; font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #9fe0d8; }
.mis-cm-verdict { flex: 1 1 220px; display: flex; flex-direction: column; justify-content: center; background: #ffffff; border: 1px solid #dde7f1; border-left: 5px solid #005eb5; border-radius: 14px; padding: 16px 20px; }
.mis-cm-verdict-lbl { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #5a6b7b; }
.mis-cm-verdict-tier { margin-top: 4px; font-size: 1.5rem; font-weight: 800; color: #00456b; line-height: 1.15; }
.mis-cm-section { margin-bottom: 16px; }
.mis-cm-section-h { font-size: 0.75rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #5a6b7b; margin-bottom: 8px; }
.mis-cm-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.mis-cm-chip { display: inline-flex; align-items: center; gap: 6px; font-size: 0.85rem; font-weight: 600; padding: 6px 12px; border-radius: 999px; border: 1px solid transparent; }
.mis-cm-ok { background: rgba(31, 157, 85, 0.14); color: #1f9d55; border-color: rgba(31, 157, 85, 0.42); }
.mis-cm-no { background: rgba(214, 69, 69, 0.12); color: #d64545; border-color: rgba(214, 69, 69, 0.42); }
.mis-cm-ico { font-weight: 800; }
.mis-cm-kpis { display: grid; grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: 12px; }
.mis-cm-kpi { background: #ffffff; border: 1px solid #dde7f1; border-top: 4px solid #109b8e; border-radius: 12px; padding: 14px 12px; text-align: center; }
.mis-cm-kpi-val { font-size: 1.6rem; font-weight: 800; color: #00456b; line-height: 1; }
.mis-cm-kpi-lbl { margin-top: 6px; font-size: 0.82rem; font-weight: 700; color: #1f2a36; }
.mis-cm-kpi-sub { margin-top: 2px; font-size: 0.7rem; color: #5a6b7b; }
.mis-cm-insights { margin: 0; padding-left: 18px; color: #1f2a36; }
.mis-cm-insights li { margin: 4px 0; font-size: 0.92rem; line-height: 1.45; }
@media (max-width: 560px) { .mis-cm-head { flex-direction: column; } .mis-cm-score { min-width: 0; } }

