(function() {
    'use strict';

    class MakeItStickAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Make It Stick`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Brookfield NHS Foundation Trust).
            this.ROLLOUT_ENVELOPE = 1.8;   // £1.8M capital rollout envelope
            this.RUN_COST = 0.42;          // £420K/year running cost
            this.ASK_TOTAL = 2.22;         // £1.8M + £420K headline ask
            this.PILOT_ADOPTION = 38;      // pilot baseline consistent adoption
            this.TARGET_ADOPTION = 75;     // benefit-realisation threshold
            this.GATE_ADOPTION = 60;       // 9-month checkpoint funding gate
            this.DEFICIT = 12;             // £12M trust deficit

            // Concept truths (the sustainable answers).
            this.TRUE_ROOT = `behavioural`;
            this.TRUE_RISK = `workaround`;
            this.TRUE_TARGET = `adoption_owned`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    adoption: 38,            // % consistent adoption (headline KPI)
                    sustain: 20,             // 24-month survival probability (0–100)
                    engage: 40,              // clinician engagement vs resistance (0–100)
                    invcase: 0,              // £M annual cost-avoidance the case credibly shows
                    budgetUsed: 0,           // £M of rollout envelope committed
                    passiveHeavy: false,     // relied on emails/guidelines (Common Error 1)
                    championDependent: false,// whole plan rests on one hero (Common Error 3)
                    alertFatigue: false,     // forcing-function without credibility (Common Error 5)
                    declaredVictory: false,  // celebrated at 9 months (Common Error 4)
                    adoptionHistory: [38],
                    sustainHistory: [20],
                    engageHistory: [40],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are a deliberately middling / wrong-leaning mix —
                // a blind click-through must not auto-win.
                state.decisions = {
                    rootcause: `evidence`,
                    risk: `mortality`,
                    target: `live`,
                    diag: 50,
                    champions: 0.4,
                    epr: 0.4,
                    audit: 0.3,
                    education: 0.4,
                    passive: 0.3,
                    forcing: `mandatory`,
                    caseType: `clinical`,
                    route: `central`,
                    value: `mention`,
                    sensitivity: 50,
                    owner: `champion`,
                    checkpoint: `celebrate`,
                    consultant: `overrule`,
                    resolve: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const rc = document.getElementById(`rootcauseInput`);
                const rk = document.getElementById(`riskInput`);
                const tg = document.getElementById(`targetInput`);
                const dg = document.getElementById(`diagInput`);
                if (rc) decisions.rootcause = rc.value;
                if (rk) decisions.risk = rk.value;
                if (tg) decisions.target = tg.value;
                if (dg) decisions.diag = parseInt(dg.value, 10);
                if (!Number.isFinite(decisions.diag) || decisions.diag < 0 || decisions.diag > 100) {
                    warn(`warn_diag_range`); return false;
                }
            } else if (round === 2) {
                const ch = document.getElementById(`championsInput`);
                const ep = document.getElementById(`eprInput`);
                const au = document.getElementById(`auditInput`);
                const ed = document.getElementById(`educationInput`);
                const pa = document.getElementById(`passiveInput`);
                const fo = document.getElementById(`forcingInput`);
                if (ch) decisions.champions = parseFloat(ch.value);
                if (ep) decisions.epr = parseFloat(ep.value);
                if (au) decisions.audit = parseFloat(au.value);
                if (ed) decisions.education = parseFloat(ed.value);
                if (pa) decisions.passive = parseFloat(pa.value);
                if (fo) decisions.forcing = fo.value;
                const parts = [decisions.champions, decisions.epr, decisions.audit, decisions.education, decisions.passive];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_alloc_negative`); return false;
                }
                const total = Math.round((parts[0] + parts[1] + parts[2] + parts[3] + parts[4]) * 10) / 10;
                if (Math.abs(total - this.ROLLOUT_ENVELOPE) > 0.001) {
                    warn(`warn_alloc_total`); return false;
                }
            } else if (round === 3) {
                const ct = document.getElementById(`caseInput`);
                const rt = document.getElementById(`routeInput`);
                const vl = document.getElementById(`valueInput`);
                const se = document.getElementById(`sensitivityInput`);
                if (ct) decisions.caseType = ct.value;
                if (rt) decisions.route = rt.value;
                if (vl) decisions.value = vl.value;
                if (se) decisions.sensitivity = parseInt(se.value, 10);
                if (!Number.isFinite(decisions.sensitivity) || decisions.sensitivity < 0 || decisions.sensitivity > 100) {
                    warn(`warn_sensitivity_range`); return false;
                }
            } else if (round === 4) {
                const ow = document.getElementById(`ownerInput`);
                const cp = document.getElementById(`checkpointInput`);
                const co = document.getElementById(`consultantInput`);
                const rs = document.getElementById(`resolveInput`);
                if (ow) decisions.owner = ow.value;
                if (cp) decisions.checkpoint = cp.value;
                if (co) decisions.consultant = co.value;
                if (rs) decisions.resolve = parseInt(rs.value, 10);
                if (!Number.isFinite(decisions.resolve) || decisions.resolve < 0 || decisions.resolve > 100) {
                    warn(`warn_resolve_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let adoptDelta = 0, sustainDelta = 0, engageDelta = 0, caseDelta = 0, spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the graveyard (Common Error: skipping the diagnosis).
                switch (d.rootcause) {
                    case `behavioural`: sustainDelta += 8; engageDelta += 4; coachKey = `coach_r1_behavioural`; break;
                    case `funding`: sustainDelta += 2; break;
                    case `evidence`: sustainDelta -= 4; coachKey = `coach_r1_evidence`; break;
                    case `technology`: sustainDelta -= 2; break;
                }
                switch (d.risk) {
                    case `workaround`: sustainDelta += 6; engageDelta += 4; if (d.rootcause === `behavioural`) coachKey = `coach_r1_sharp`; break;
                    case `mortality`: sustainDelta -= 2; break;
                    case `cost`: break;
                    case `none`: sustainDelta -= 6; engageDelta -= 4; coachKey = `coach_r1_none`; break;
                }
                switch (d.target) {
                    case `adoption_owned`: sustainDelta += 8; coachKey = (d.rootcause === `behavioural` && d.risk === `workaround`) ? `coach_r1_sharp` : coachKey; break;
                    case `live`: sustainDelta -= 4; coachKey = `coach_r1_live`; break;
                    case `golive`: sustainDelta -= 6; ds.declaredVictory = true; coachKey = `coach_r1_golive`; break;
                }
                if (d.diag >= 60) { sustainDelta += 5; engageDelta += 3; }
                else if (d.diag <= 25) { sustainDelta -= 5; coachKey = `coach_r1_lowdiag`; }

                summaryKey = (d.rootcause === `behavioural` && d.risk === `workaround` && d.target === `adoption_owned`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Choose the knowledge-translation bundle (Common Error 1: passive dissemination).
                // Active tactics drive adoption with diminishing returns; passive is near-dead weight.
                const ch = d.champions, ep = d.epr, au = d.audit, ed = d.education, pa = d.passive;
                const activeSpend = ch + ep + au + ed;

                // Adoption uplift: active tactics convert the 44% inconsistent + 18% workaround.
                // Forcing-function (EPR) and education reach the workaround users; champions+audit anchor it socially.
                adoptDelta += ep * 10 + ed * 7 + ch * 6 + au * 6;
                // Diminishing returns on any single overweighted lever.
                const maxLever = Math.max(ch, ep, au, ed);
                if (maxLever > 0.9) adoptDelta -= (maxLever - 0.9) * 8;

                // Passive dissemination buys almost nothing and is what killed 11 of 14.
                adoptDelta += pa * 1;
                if (pa >= 0.6) { ds.passiveHeavy = true; adoptDelta -= (pa - 0.5) * 6; sustainDelta -= 4; coachKey = `coach_r2_passive`; }

                // Champions sustained past the pilot, audit-and-feedback and EPR build the survival probability.
                sustainDelta += ch * 5 + au * 6 + ep * 4 - pa * 3;
                engageDelta += ch * 7 + ed * 5 + au * 4;

                // Forcing-function balance: balanced default + override beats both extremes.
                switch (d.forcing) {
                    case `balanced`: adoptDelta += 5; sustainDelta += 6; engageDelta += 4; if (coachKey === `coach_default`) coachKey = `coach_r2_balanced`; break;
                    case `mandatory`: adoptDelta += 8; engageDelta -= 8; ds.alertFatigue = true; coachKey = `coach_r2_mandatory`; break;
                    case `persuasion`: adoptDelta -= 4; engageDelta += 4; coachKey = `coach_r2_persuasion`; break;
                }

                spend += this.ROLLOUT_ENVELOPE;   // the whole envelope is committed this round

                const balancedActive = activeSpend >= 1.4 && pa <= 0.4;
                summaryKey = (balancedActive && d.forcing === `balanced`) ? `sum_r2_good` :
                             (ds.passiveHeavy ? `sum_r2_passive` : `sum_r2_weak`);
            } else if (round === 3) {
                // Build the board case (Common Error 2: clinical-benefit-only case).
                switch (d.caseType) {
                    case `costavoid`: caseDelta += 2.6; sustainDelta += 6; coachKey = `coach_r3_costavoid`; break;
                    case `clinical`: caseDelta += 0.6; sustainDelta -= 4; coachKey = `coach_r3_clinical`; break;
                    case `mandate`: caseDelta += 0.4; sustainDelta -= 2; engageDelta -= 2; coachKey = `coach_r3_mandate`; break;
                }
                switch (d.route) {
                    case `investtosave`: caseDelta += 1.0; sustainDelta += 6; engageDelta += 2; break;
                    case `central`: caseDelta += 0.2; sustainDelta -= 2; coachKey = (coachKey === `coach_default`) ? `coach_r3_central` : coachKey; break;
                    case `defer`: caseDelta -= 0.6; sustainDelta -= 6; coachKey = `coach_r3_defer`; break;
                }
                switch (d.value) {
                    case `quantify`: caseDelta += 0.8; sustainDelta += 4; break;
                    case `mention`: caseDelta += 0.2; break;
                    case `skip`: caseDelta -= 0.2; coachKey = (coachKey === `coach_default`) ? `coach_r3_skipvalue` : coachKey; break;
                }
                // Adoption-sensitivity floor: a case stress-tested to a realistic floor is fundable.
                if (d.sensitivity >= 35 && d.sensitivity <= 65) { caseDelta += 0.6; sustainDelta += 5; if (d.caseType === `costavoid`) coachKey = `coach_r3_sensitivity`; }
                else if (d.sensitivity > 80) { caseDelta -= 0.4; sustainDelta -= 3; coachKey = `coach_r3_overoptimistic`; }
                else if (d.sensitivity < 20) { sustainDelta -= 2; }

                summaryKey = (d.caseType === `costavoid` && d.route === `investtosave` && d.sensitivity <= 65) ? `sum_r3_good` :
                             (d.caseType === `clinical` ? `sum_r3_clinical` : `sum_r3_weak`);
            } else if (round === 4) {
                // Routinize under resistance (Common Errors 3, 4, 5).
                switch (d.owner) {
                    case `governance`: sustainDelta += 16; engageDelta += 6; adoptDelta += 4; ds.championDependent = false; coachKey = `coach_r4_governance`; break;
                    case `champion`: sustainDelta -= 8; adoptDelta += 4; ds.championDependent = true; coachKey = `coach_r4_champion`; break;
                    case `project`: sustainDelta -= 4; coachKey = `coach_r4_project`; break;
                }
                switch (d.checkpoint) {
                    case `path75`: sustainDelta += 12; adoptDelta += 8; coachKey = (d.owner === `governance`) ? `coach_r4_path75` : coachKey; break;
                    case `celebrate`: sustainDelta -= 10; adoptDelta -= 6; ds.declaredVictory = true; coachKey = `coach_r4_celebrate`; break;
                    case `defend`: sustainDelta -= 2; break;
                }
                // The consultant's algorithm challenge — resistance as data, not obstruction.
                switch (d.consultant) {
                    case `engage`: engageDelta += 12; sustainDelta += 8; adoptDelta += 5; if (ds.alertFatigue) { ds.alertFatigue = false; } coachKey = (d.owner === `governance` && d.checkpoint === `path75`) ? `coach_r4_master` : coachKey; break;
                    case `overrule`: engageDelta -= 12; adoptDelta -= 8; sustainDelta -= 6; ds.alertFatigue = true; coachKey = `coach_r4_overrule`; break;
                    case `concede`: adoptDelta -= 10; sustainDelta -= 8; engageDelta += 2; coachKey = `coach_r4_concede`; break;
                }
                if (d.resolve >= 60) { sustainDelta += 5; engageDelta += 3; }
                else if (d.resolve <= 25) { sustainDelta -= 4; engageDelta -= 3; }

                summaryKey = (d.owner === `governance` && d.checkpoint === `path75` && d.consultant === `engage`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting: the £1.8M rollout envelope is metered (committed in R2).
            ds.budgetUsed = Math.min(this.ROLLOUT_ENVELOPE, Math.round((ds.budgetUsed + spend) * 100) / 100);

            // Apply deltas. Adoption is a %; sustain/engage are 0–100; invcase is £M.
            ds.adoption = Math.max(0, Math.min(100, Math.round((ds.adoption + adoptDelta) * 10) / 10));
            ds.sustain = Math.max(0, Math.min(100, Math.round(ds.sustain + sustainDelta)));
            ds.engage = Math.max(0, Math.min(100, Math.round(ds.engage + engageDelta)));
            ds.invcase = Math.max(0, Math.round((ds.invcase + caseDelta) * 100) / 100);

            ds.adoptionHistory.push(ds.adoption);
            ds.sustainHistory.push(ds.sustain);
            ds.engageHistory.push(ds.engage);

            // v1.1.0 — persist the composite where the gradebook reads it (was never written).
            const _score = this._composite(ds);
            if (!ds.performance || typeof ds.performance !== `object`) ds.performance = {};
            ds.performance.overallScore = _score;
            ds.score = _score;

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing(window.mySimulation.state);
            }, 500);

            return {
                period: state.currentPeriod,
                adoption: ds.adoption,
                adoptDelta: Math.round(adoptDelta * 10) / 10,
                sustain: ds.sustain,
                sustainDelta: Math.round(sustainDelta),
                engage: ds.engage,
                engageDelta: Math.round(engageDelta),
                invcase: ds.invcase,
                caseDelta: Math.round(caseDelta * 100) / 100,
                budgetUsed: ds.budgetUsed,
                passiveHeavy: ds.passiveHeavy,
                championDependent: ds.championDependent,
                alertFatigue: ds.alertFatigue,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg,
                score: _score,
                overallScore: _score
            };
        }

        _fmtMoney(v) {
            // Locale-aware GBP: English "£1.80M" (symbol before, dot decimal);
            // Spanish "1,80 M£" (symbol after, comma decimal).
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const sign = v < 0 ? `-` : ``;
            const abs = Math.abs(v);
            if (lang === `es`) {
                return `${sign}${abs.toFixed(2).replace(`.`, `,`)} M£`;
            }
            return `${sign}£${abs.toFixed(2)}M`;
        }

        _fmtMoney1(v) {
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const sign = v < 0 ? `-` : ``;
            const abs = Math.abs(v);
            if (lang === `es`) {
                return `${sign}${abs.toFixed(1).replace(`.`, `,`)} M£`;
            }
            return `${sign}£${abs.toFixed(1)}M`;
        }

        _fmtPct(v) {
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const n = Math.round(Number(v));
            return lang === `es` ? `${n} %` : `${n}%`;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`adoptDisplay`, `domainState.adoption`, (v) => {
                const card = document.querySelector(`.sticksim-card-adopt`);
                if (card) {
                    card.classList.toggle(`sticksim-adopt-target`, Number(v) >= self.TARGET_ADOPTION);
                    card.classList.toggle(`sticksim-adopt-low`, Number(v) < self.GATE_ADOPTION);
                }
                return self._fmtPct(v);
            });
            uiManager.bind(`sustainDisplay`, `domainState.sustain`, (v) => {
                const card = document.querySelector(`.sticksim-card-sustain`);
                if (card) {
                    card.classList.toggle(`sticksim-sustain-high`, Number(v) >= 65);
                    card.classList.toggle(`sticksim-sustain-low`, Number(v) <= 30);
                }
                return Math.round(Number(v));
            });
            uiManager.bind(`engageDisplay`, `domainState.engage`, (v) => Math.round(Number(v)));
            uiManager.bind(`caseDisplay`, `domainState.invcase`, (v) => {
                const card = document.querySelector(`.sticksim-card-case`);
                if (card) {
                    card.classList.toggle(`sticksim-case-positive`, Number(v) >= self.ASK_TOTAL);
                    card.classList.toggle(`sticksim-case-negative`, Number(v) > 0 && Number(v) < 1.0);
                }
                return self._fmtMoney1(Number(v));
            });
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => {
                return self._fmtMoney(Number(v)) + ` / ` + self._fmtMoney(self.ROLLOUT_ENVELOPE);
            });

            // Diagnostic-rigour slider readout (R1).
            const dg = document.getElementById(`diagInput`);
            const dgReadout = document.getElementById(`diagReadout`);
            if (dg && dgReadout) {
                dgReadout.textContent = dg.value;
                dg.addEventListener(`input`, function() { dgReadout.textContent = dg.value; });
            }

            // Adoption-sensitivity slider readout (R3).
            const se = document.getElementById(`sensitivityInput`);
            const seReadout = document.getElementById(`sensitivityReadout`);
            if (se && seReadout) {
                seReadout.textContent = se.value;
                se.addEventListener(`input`, function() { seReadout.textContent = se.value; });
            }

            // Rollout-envelope live total (must hit £1.8M) (R2).
            const allocIds = [`championsInput`, `eprInput`, `auditInput`, `educationInput`, `passiveInput`];
            const allocReadout = document.getElementById(`allocReadout`);
            const recompute = function() {
                let total = 0;
                allocIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total * 10) / 10;
                if (allocReadout) allocReadout.textContent = total.toFixed(1);
                const bar = document.querySelector(`.sticksim-alloc-readout`);
                if (bar) bar.style.color = (Math.abs(total - self.ROLLOUT_ENVELOPE) > 0.001) ? `#d64545` : ``;
            };
            allocIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

