        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.adoptionHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                stickChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.adoptionHistory },
                        { data: ds.sustainHistory },
                        { data: ds.engageHistory }
                    ]
                }
            };
        }

        _composite(ds) {
            // Verbatim v1.0.0 composite (was inline in getPerformanceSummary), extracted so the
            // per-period persisted score and the completion summary are identical by construction.
            const adoption = Math.round(ds.adoption);
            const sustain = Math.round(ds.sustain);
            const engage = Math.round(ds.engage);
            const invcase = ds.invcase;
            const caseScore = Math.max(0, Math.min(100, (invcase / this.ASK_TOTAL) * 100));
            return Math.round(adoption * 0.30 + sustain * 0.32 + engage * 0.20 + caseScore * 0.18);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const adoption = Math.round(ds.adoption);
            const sustain = Math.round(ds.sustain);
            const engage = Math.round(ds.engage);
            const invcase = ds.invcase;

            // Composite: adoption and sustainability dominate; engagement and the
            // investment case round it out (case normalised: full marks at the £2.22M ask).
            const composite = this._composite(ds);

            const clearedGate = adoption >= this.GATE_ADOPTION;
            const hitTarget = adoption >= this.TARGET_ADOPTION;
            const willSustain = sustain >= 65 && !ds.championDependent && !ds.declaredVictory;
            const funded = invcase >= this.ASK_TOTAL;
            const graveyard = adoption < this.GATE_ADOPTION || ds.passiveHeavy || (ds.championDependent && sustain < 50);

            // v1.1.0 — tier labels moved to i18n keys (were hardcoded English).
            let tierKey = `grade_graveyard`;
            if (hitTarget && willSustain && funded && composite >= 78) tierKey = `grade_embedded`;
            else if (clearedGate && willSustain) tierKey = `grade_sticks`;
            else if (clearedGate && composite >= 58) tierKey = `grade_fragile`;
            else if (graveyard) tierKey = `grade_graveyard`;
            else if (composite >= 50) tierKey = `grade_mixed`;
            const performance = window.mySimulation.t(tierKey);

            const insights = [];
            if (hitTarget && willSustain && funded) insights.push(window.mySimulation.t(`insight_embedded`));
            else if (graveyard) insights.push(window.mySimulation.t(`insight_graveyard`));
            else insights.push(window.mySimulation.t(`insight_fragile`));

            if (ds.passiveHeavy) insights.push(window.mySimulation.t(`insight_passive`));
            if (ds.championDependent) insights.push(window.mySimulation.t(`insight_champion`));
            if (ds.declaredVictory) insights.push(window.mySimulation.t(`insight_victory`));
            if (ds.alertFatigue) insights.push(window.mySimulation.t(`insight_alertfatigue`));
            if (!funded && invcase > 0) insights.push(window.mySimulation.t(`insight_unfunded`));
            if (hitTarget && engage >= 65) insights.push(window.mySimulation.t(`insight_engaged`));

            return {
                adoption: adoption,
                sustain: sustain,
                engage: engage,
                invcase: invcase,
                clearedGate: clearedGate,
                hitTarget: hitTarget,
                willSustain: willSustain,
                funded: funded,
                graveyard: graveyard,
                passiveHeavy: !!ds.passiveHeavy,
                championDependent: !!ds.championDependent,
                declaredVictory: !!ds.declaredVictory,
                budgetUsed: ds.budgetUsed,
                composite: composite,
                performance: performance,
                tierKey: tierKey,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k) => window.mySimulation.t(k);
            if (!summary || summary.composite == null) {
                return `<div class="mis-cm"><p class="mis-cm-incomplete">` + t(`cm_incomplete`) + `</p></div>`;
            }
            const s = summary;
            const chip = (ok, label) => `<span class="mis-cm-chip ` + (ok ? `mis-cm-ok` : `mis-cm-no`) + `">` +
                `<span class="mis-cm-ico">` + (ok ? `✓` : `✕`) + `</span>` + label + ` · ` +
                (ok ? t(`cm_met`) : t(`cm_missed`)) + `</span>`;
            const kpi = (label, val, sub) => `<div class="mis-cm-kpi"><div class="mis-cm-kpi-val">` + val +
                `</div><div class="mis-cm-kpi-lbl">` + label + `</div>` +
                (sub ? `<div class="mis-cm-kpi-sub">` + sub + `</div>` : ``) + `</div>`;
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `` +
`<div class="mis-cm">` +
  `<div class="mis-cm-head">` +
    `<div class="mis-cm-score"><div class="mis-cm-score-num">` + Math.round(s.composite) +
       `<span class="mis-cm-score-den">/100</span></div>` +
       `<div class="mis-cm-score-lbl">` + t(`cm_score`) + `</div></div>` +
    `<div class="mis-cm-verdict"><div class="mis-cm-verdict-lbl">` + t(`cm_verdict`) + `</div>` +
       `<div class="mis-cm-verdict-tier">` + s.performance + `</div></div>` +
  `</div>` +
  `<div class="mis-cm-section"><div class="mis-cm-section-h">` + t(`cm_targets`) + `</div>` +
    `<div class="mis-cm-chips">` + chip(!!s.clearedGate, t(`cm_t_gate`)) + chip(!!s.hitTarget, t(`cm_t_target`)) +
      chip(!!s.willSustain, t(`cm_t_sustain`)) + chip(!!s.funded, t(`cm_t_funded`)) + `</div></div>` +
  `<div class="mis-cm-section"><div class="mis-cm-section-h">` + t(`cm_kpis`) + `</div>` +
    `<div class="mis-cm-kpis">` +
      kpi(t(`adopt_label`), (Math.round(Number(s.adoption) * 10) / 10) + `%`, t(`cm_sub_adoption`)) +
      kpi(t(`sustain_label`), Math.round(s.sustain), t(`cm_sub_sustain`)) +
      kpi(t(`engage_label`), Math.round(s.engage), t(`cm_sub_engage`)) +
      kpi(t(`case_label`), `£` + (Math.round(Number(s.invcase) * 100) / 100) + `M`, t(`cm_sub_case`)) +
    `</div></div>` +
  (insights ? `<div class="mis-cm-section"><div class="mis-cm-section-h">` + t(`cm_insights`) +
      `</div><ul class="mis-cm-insights">` + insights + `</ul></div>` : ``) +
`</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.passiveHeavy) return window.mySimulation.t(`hint_passive`);
            if (ds.alertFatigue) return window.mySimulation.t(`hint_alertfatigue`);
            if (ds.championDependent && state.currentPeriod >= 4) return window.mySimulation.t(`hint_champion`);
            if (state.currentPeriod >= 2 && ds.adoption < this.GATE_ADOPTION) return window.mySimulation.t(`hint_gate`);
            if (state.currentPeriod >= 3 && ds.invcase < 1.0) return window.mySimulation.t(`hint_case`);
            if (ds.adoption >= this.TARGET_ADOPTION && ds.sustain >= 65 && ds.engage >= 60) return window.mySimulation.t(`hint_strong`);
            return null;
        }

