                    col_case:               `Caso`
                }
            };
        }
    }

    document.addEventListener(`DOMContentLoaded`, () => {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new MakeItStickAdapter(), {
            simulationType: `make_it_stick`,
            maxPeriods: 4,
            autoSaveInterval: 30000
        });
    });

})();
